var t=[{title:`Wat lage impact betekent`,text:`Bewegingen met lage impact houden meestal minstens één voet op de grond, of gebruiken apparatuur zoals een stationaire fiets om de grondimpact weg te nemen. Lage impact kan nog steeds hoge intensiteit zijn en je gewrichten nog steeds belasten. Een zwaar fietsinterval kan je hart en longen belasten, en sommige stepoefeningen vragen nog veel van je knieën en heupen.`},{title:`Goede bewegingskeuzes`,text:`Stevig wandelen, marcheren, step touches, schaduwboksen zonder te stuiteren, beheerste step-ups, fietsen en elliptische trainers zijn allemaal praktische opties. Wissel in een kleine kamer stevig marcheren af met bewuste zijwaartse stappen of lichte stoten. Kies bewegingen die stabiel voelen en voeg geen snelle draaiingen toe alleen om het zwaarder te maken.`},{title:`Voorbeeld`,text:`Herhaal na een geleidelijke warming-up zes keer 45 seconden stevig marcheren en 45 seconden rustig wandelen. Bepaal je eigen tempo en rust; kopieer niet de snelheid van een ander. Verleng om op te bouwen de actieve periodes of de hele training voordat je voor explosieve snelheid gaat.`},{title:`Stem af op de reden waarom je impact vermijdt`,text:`Is geluid het probleem, dan kan het weglaten van sprongen genoeg zijn. Is een knie, enkel of rug gevoelig, dan kan zelfs gewoon stappen pijn doen en moet je misschien naar een arts of fysiotherapeut. Training met lage impact is geen behandeling en garandeert geen pijnverlichting.`},{title:`TrainUp gebruiken`,text:`Stel in Profiel in of springen mag, hoeveel geluid mag, je ondergrond, je niveau, je uitrusting en eventuele beperkingen per lichaamsdeel. Het schema gebruikt ze allemaal samen en laat, als springen uit staat, touwtjespringen en andere sprongoefeningen weg. Marcheren of fietsen kan de inspanning daarvoor in de plaats op peil houden. Beoordeel de inspanning van de training achteraf zoals gewoonlijk.`}];var a=[{label:`Beweegaanbevelingen van de CDC voor volwassenen`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`CDC: de intensiteit van activiteit meten en de praattest`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var i={sections:t,sources:a};export{i as default,t as sections,a as sources};